c(27, "§5.1 table (verbatim); §5.1; §5.2 table (verbatim); §5.2; §5.6", "monetization", "The monetisation model — a free app with ads whose only purchases are ad-removal subscriptions (Monthly $0.99 / Yearly $9.99; 99 ₽ / 699 ₽), added in 1.1.1 on 2023-04-03; no feature is listed as paid (verbatim): " + table("## 5.1 The monetisation model", 0) + " — PAID_EXPLICIT 2 (ru 1, us 1, both 5★, both ad removal, both satisfied); WOULD_PAY_INTENT 3 (for a widget, to support the developer, for a lifetime option); TRIAL_USER 1 charged after cancelling; U:money_any 36 (5.86%), 20 of them ad complaints; segment rates (verbatim): " + table("## 5.2 Segment rates", 0) + " — 'reviews that criticise ads are the churn segment': 7 of the 20 carry a lost-user signal against 5 of the 536 reviews with no money code; no conversion, refund or retention rate; no finding about who pays ('two paying reviewers are two people'); no price elasticity; no finding that a widget would sell subscriptions — one reviewer said so in 2023, 'an experiment to run, not a result'.", "ad-removal subscription only", "mixed", "PAID 2 / 0.33%; WOULD_PAY 3; TRIAL 1; money_any 36 / 5.86% (ads 20); ads_negative → lost_user 7 of 20 vs 5 of 536", "none", "Weak", "generalisable", ["11651806786", "13254705653", "10456809560", "11505099084", "11641762030", "13524890756"], "", "")

c(28, "§5.3 table (verbatim); §5.3; §5.4", "insight", "What buyers say they bought and why (verbatim): " + table("## 5.3 What buyers say", 0) + " — not starting a tracker with ads ('paid at once… after paying a gorgeous screen appeared; respect to your marketer', ru 5★); ads were annoying ('the were ads before I paid for them. But I like this ap', us 5★); supporting the developer (intent: 'I see the ad-free subscription as a plus; thinking of using it to support you', kz); a widget (intent); what goes wrong after purchase — nothing: no paying reviewer reports a problem; the two billing complaints come from reviewers who did not intend to pay.", "post-purchase thank-you screen", "purchase-driver", "buyers 2 (both satisfied); intent 3; post-purchase problems 0; billing complaints from non-buyers 2", "do", "Weak", "generalisable", ["11651806786", "13254705653", "11505099084", "10456809560", "10097280052", "13524890756"], "", "an ad-removal purchase in an otherwise fully free app produces zero post-purchase complaints")

c(29, "§5.5 table (verbatim); §5.5", "monetization", "Upgrade barriers among non-buyers (verbatim): " + table("## 5.5 Upgrade barriers", 0) + " — 'the barrier is format and framing, not price': the only amount a reviewer names is 100₽ and the one US reviewer to mention price calls it 'reasonably priced'; ad removal is a subscription and two reviewers ask for it for life; some accept ads instead of paying ('you don't have to pay, just watch an ad', pt).", "subscription-only ad removal; perceived paywall", "blocked-conversion", "PAYWALL_PERCEIVED 6 / 0.98%; WANT_ONE_TIME 2; SUBSCRIPTION_OBJECTION 2; FUTURE_WORRY 3; accept ads 2", "product-rule", "Emerging", "generalisable", ["11890941612", "13029179785", "13840823158", "11641762030", "14162589436", "12839988426", "10683386706", "13433119107", "13712536946", "12548923831", "13598745387", "14510416958"], "", "")

